    total_distance = 0
    count = 0
    for i in range(2**n):
        for j, distance in graph[i]:
            if distance > 0:
                total_distance += math.log(distance)
                count += 1
    if count == 0:
        return 0
    average_distance = total_distance / count
    return -average_distance

